{"function": "() => {
  const rows = document.querySelectorAll('table tbody tr');
  const data = [];
  rows.forEach(row => {
    const cells = row.querySelectorAll('td');
    if (cells.length >= 4) {
      const codeCell = cells[0];
      const nameCell = cells[1];
      const menCell = cells[2];
      const womenCell = cells[3];
      const totalCell = cells[4];
      const code = codeCell.textContent.trim();
      const name = nameCell.textContent.trim();
      const total = totalCell.textContent.trim();
      // Skip if code is empty (maybe header)
      if (code && name && total && !isNaN(parseInt(total))) {
        data.push({ code, name, total });
      }
    }
  });
  return data;
}"}

